head.b:skin:
    /* =========================================================================
       UBAH WARNA & VARIABEL TEMA DI SINI
       ========================================================================= */
    :root {
      --kv-bg: #F6F7FB;
      --kv-surface: #FFFFFF;
      --kv-surface-2: #F0F2F8;
      --kv-border: #E5E8F0;
      --kv-text: #20243A;
      --kv-text-muted: #737B91;
      --kv-accent: #6558D9;       /* Ubah warna aksen utama di sini */
      --kv-accent-hover: #5447C5;
      --kv-neon: #38A99B;
      --kv-success: #16A34A;
      --kv-warning: #D97706;
      --kv-danger: #DC2626;
      --kv-font-sans: 'Plus Jakarta Sans', system-ui, -apple-system, sans-serif;
      --kv-font-mono: 'JetBrains Mono', ui-monospace, monospace;
      --kv-radius: 14px;
    }

    html.dark {
      --kv-bg: #0F111A;
      --kv-surface: #171A27;
      --kv-surface-2: #20243A;
      --kv-border: #2B304C;
      --kv-text: #DEE1FE;
      --kv-text-muted: #A0A7B8;
      --kv-accent: #A69AF4;       /* Ubah warna aksen dark mode di sini */
      --kv-accent-hover: #B8AEFF;
      --kv-neon: #70CFC0;
      --kv-success: #22C55E;
      --kv-warning: #F59E0B;
      --kv-danger: #EF4444;
    }

    *, *::before, *::after { box-sizing: border-box; }
    html, body {
      margin: 0; padding: 0;
      background: var(--kv-bg);
      color: var(--kv-text);
      font-family: var(--kv-font-sans);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
    }

    a { color: inherit; text-decoration: none; }
    button, input, select, textarea { font-family: inherit; }
    button:focus-visible, a:focus-visible, input:focus-visible, select:focus-visible, textarea:focus-visible {
      outline: 2px solid var(--kv-accent);
      outline-offset: 2px;
    }

    .kv-mono { font-family: var(--kv-font-mono); font-variant-numeric: tabular-nums; }
    .kv-container { max-width: 1200px; margin: 0 auto; padding: 0 20px; }

    /* Top Bar (3-Zone Contract) */
    .kv-header {
      position: sticky; top: 0; z-index: 40;
      background: var(--kv-bg); /* Fallback untuk browser lama tanpa color-mix */
      background: color-mix(in srgb, var(--kv-bg) 88%, transparent);
      backdrop-filter: blur(12px);
      border-bottom: 1px solid var(--kv-border);
    }
    .kv-header-inner {
      display: flex; align-items: center; justify-content: space-between;
      gap: 32px; height: 64px;
    }
    .kv-brand {
      font-size: 1.25rem; font-weight: 800; letter-spacing: -0.02em;
      white-space: nowrap; flex-shrink: 0;
      color: var(--kv-text);
    }
    .kv-nav { display: flex; align-items: center; gap: 24px; }
    .kv-nav-link {
      font-size: 0.875rem; font-weight: 500; color: var(--kv-text-muted);
      white-space: nowrap; padding: 6px 2px; border-bottom: 2px solid transparent;
      transition: color 0.16s ease, border-color 0.16s ease;
    }
    .kv-nav-link:hover, .kv-nav-link.active {
      color: var(--kv-text); border-bottom-color: var(--kv-accent);
    }
    .kv-btn {
      display: inline-flex; align-items: center; justify-content: center; gap: 8px;
      padding: 9px 18px; border-radius: 8px; font-size: 0.875rem; font-weight: 600;
      border: 1px solid transparent; cursor: pointer; white-space: nowrap;
      transition: transform 0.15s ease, background-color 0.15s ease, border-color 0.15s ease;
    }
    .kv-btn:active { transform: scale(0.98); }
    .kv-btn-primary { background: var(--kv-accent); color: #FFFFFF; }
    .kv-btn-primary:hover { background: var(--kv-accent-hover); }
    .kv-btn-ghost {
      background: var(--kv-surface); color: var(--kv-text); border-color: var(--kv-border);
    }
    .kv-btn-ghost:hover { border-color: var(--kv-accent); }
    .kv-btn-danger { background: var(--kv-danger); color: #FFFFFF; }

    /* Hero Featured */
    .kv-hero {
      display: grid; grid-template-columns: 1.4fr 1fr; gap: 32px; align-items: stretch;
      background: var(--kv-surface); border: 1px solid var(--kv-border);
      border-radius: 14px; padding: 32px; margin-top: 28px;
    }
    .kv-hero-title {
      font-size: clamp(1.75rem, 3.2vw, 2.75rem); font-weight: 800; line-height: 1.15;
      margin: 10px 0 14px; text-wrap: balance;
    }
    .kv-meta-line {
      display: flex; flex-wrap: wrap; align-items: center; gap: 8px;
      font-size: 0.8125rem; color: var(--kv-text-muted);
    }
    .kv-cover-wrap {
      position: relative; aspect-ratio: 3 / 4; border-radius: 10px; overflow: hidden;
      background: var(--kv-surface-2); border: 1px solid var(--kv-border);
    }
    .kv-cover-wrap img { width: 100%; height: 100%; object-fit: cover; display: block; }

    /* Grids & Cards */
    .kv-section { margin-top: 44px; }
    .kv-section-head {
      display: flex; align-items: baseline; justify-content: space-between; gap: 16px;
      margin-bottom: 18px;
    }
    .kv-section-title { font-size: 1.25rem; font-weight: 700; margin: 0; }
    .kv-grid {
      display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 20px;
    }
    .kv-card {
      background: var(--kv-surface); border: 1px solid var(--kv-border);
      border-radius: var(--kv-radius); overflow: hidden;
      transition: transform 0.18s ease, border-color 0.18s ease;
      cursor: pointer; display: flex; flex-direction: column;
    }
    .kv-card:hover { transform: translateY(-3px); border-color: var(--kv-accent); }
    .kv-card-body { padding: 14px; display: flex; flex-direction: column; gap: 6px; flex: 1; }
    .kv-card-title { font-size: 1rem; font-weight: 700; margin: 0; line-height: 1.3; }

    /* Filters & Inputs */
    .kv-toolbar {
      display: flex; flex-wrap: wrap; gap: 12px; align-items: center;
      padding: 16px; background: var(--kv-surface); border: 1px solid var(--kv-border);
      border-radius: var(--kv-radius); margin-top: 24px;
    }
    .kv-input, .kv-select, .kv-textarea {
      background: var(--kv-bg); color: var(--kv-text);
      border: 1px solid var(--kv-border); border-radius: 8px;
      padding: 9px 12px; font-size: 0.875rem;
    }
    .kv-input { min-width: 220px; flex: 1; }
    .kv-textarea { width: 100%; min-height: 90px; resize: vertical; }

    /* Chapter List & Detail */
    .kv-detail-grid {
      display: grid; grid-template-columns: 280px 1fr; gap: 32px; margin-top: 28px;
    }
    .kv-chapter-row {
      display: flex; align-items: center; justify-content: space-between; gap: 16px;
      padding: 12px 16px; border-bottom: 1px solid var(--kv-border);
      cursor: pointer; transition: background-color 0.15s ease;
    }
    .kv-chapter-row:hover { background: var(--kv-surface-2); }

    /* Reader */
    .kv-reader-bar {
      position: sticky; top: 0; z-index: 50;
      background: var(--kv-surface); border-bottom: 1px solid var(--kv-border);
      padding: 10px 20px; display: flex; flex-wrap: wrap; align-items: center;
      justify-content: space-between; gap: 12px;
    }
    .kv-reader-progress {
      position: fixed; top: 0; left: 0; height: 3px; background: var(--kv-neon);
      z-index: 60; transition: width 0.12s linear;
    }
    .kv-reader-canvas {
      margin: 0 auto; padding: 20px 12px 64px; display: flex; flex-direction: column;
      align-items: center; gap: 8px;
    }
    .kv-reader-canvas img {
      width: 100%; height: auto; display: block; border-radius: 4px;
      background: var(--kv-surface-2);
    }

    /* Admin Panel */
    .kv-admin-grid {
      display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 16px;
      margin: 20px 0;
    }
    .kv-stat-box {
      background: var(--kv-surface); border: 1px solid var(--kv-border);
      border-radius: var(--kv-radius); padding: 18px;
    }
    .kv-stat-val { font-size: 1.75rem; font-weight: 800; margin-top: 4px; }
    .kv-table-wrap {
      overflow-x: auto; background: var(--kv-surface);
      border: 1px solid var(--kv-border); border-radius: var(--kv-radius);
    }
    table.kv-table { width: 100%; border-collapse: collapse; font-size: 0.875rem; }
    table.kv-table th, table.kv-table td {
      text-align: left; padding: 12px 14px; border-bottom: 1px solid var(--kv-border);
    }
    table.kv-table th { color: var(--kv-text-muted); font-weight: 600; font-size: 0.75rem; }

    /* Footer */
    .kv-footer {
      margin-top: 64px; border-top: 1px solid var(--kv-border);
      padding: 32px 0; color: var(--kv-text-muted); font-size: 0.875rem;
    }
    .kv-footer-inner {
      display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: 16px;
    }

    /* Admin Console SaaS Premium */
    .kv-admin-shell { display: flex; align-items: stretch; min-height: 100vh; }
    .kv-admin-side {
      width: 248px; flex-shrink: 0; position: sticky; top: 0; height: 100vh;
      display: flex; flex-direction: column; overflow-y: auto;
      background: var(--kv-surface); border-right: 1px solid var(--kv-border);
      padding: 20px 14px;
    }
    .kv-admin-logo {
      font-weight: 800; font-size: 1.05rem; letter-spacing: -0.02em;
      display: flex; align-items: center; gap: 8px; padding: 4px 8px 14px;
    }
    .kv-admin-logo span {
      color: var(--kv-neon); font-size: 0.6875rem; font-weight: 700;
      letter-spacing: 0.09em; text-transform: uppercase;
    }
    .kv-admin-side-label {
      font-size: 0.6875rem; font-weight: 700; letter-spacing: 0.1em;
      text-transform: uppercase; color: var(--kv-text-muted);
      padding: 14px 10px 6px;
    }
    .kv-admin-nav { display: flex; flex-direction: column; gap: 4px; }
    .kv-admin-nav-item {
      display: flex; align-items: center; gap: 10px; width: 100%;
      padding: 9px 10px; border-radius: 8px; border: none; background: none;
      color: var(--kv-text-muted); font-size: 0.875rem; font-weight: 600;
      cursor: pointer; text-align: left; white-space: nowrap;
      transition: background-color 0.15s ease, color 0.15s ease;
    }
    .kv-admin-nav-item:hover { background: var(--kv-surface-2); color: var(--kv-text); }
    .kv-admin-nav-item.active {
      color: var(--kv-text);
      background: linear-gradient(90deg, var(--kv-surface-2), transparent);
      box-shadow: inset 2px 0 0 var(--kv-accent);
    }
    .kv-admin-nav-badge {
      margin-left: auto; min-width: 20px; height: 20px; padding: 0 6px;
      border-radius: 999px; background: var(--kv-danger); color: #FFFFFF;
      font-size: 0.6875rem; font-weight: 700;
      display: inline-flex; align-items: center; justify-content: center;
    }
    .kv-admin-side-foot {
      margin-top: auto; padding-top: 14px; border-top: 1px solid var(--kv-border);
      display: flex; flex-direction: column; gap: 10px;
    }
    .kv-admin-chip {
      display: inline-flex; align-items: center; gap: 8px;
      font-size: 0.75rem; color: var(--kv-text-muted); padding: 0 4px;
    }
    .kv-admin-chip .dot {
      width: 8px; height: 8px; border-radius: 50%; flex-shrink: 0;
      background: var(--kv-success); box-shadow: 0 0 8px var(--kv-success);
    }
    .kv-admin-chip.off .dot { background: var(--kv-warning); box-shadow: 0 0 8px var(--kv-warning); }
    .kv-admin-main { flex: 1; min-width: 0; max-width: 1080px; padding: 28px 32px 48px; }
    .kv-admin-topbar {
      display: flex; align-items: flex-start; justify-content: space-between;
      gap: 16px; flex-wrap: wrap; margin-bottom: 22px;
    }
    .kv-admin-title { font-size: 1.5rem; font-weight: 800; margin: 0; letter-spacing: -0.02em; }
    .kv-admin-sub { color: var(--kv-text-muted); font-size: 0.875rem; margin: 4px 0 0; }
    .kv-admin-top-actions { display: flex; gap: 10px; flex-wrap: wrap; }
    .kv-stat-card {
      background: var(--kv-surface); border: 1px solid var(--kv-border);
      border-radius: 14px; padding: 18px; position: relative; overflow: hidden;
    }
    .kv-stat-card::after {
      content: ''; position: absolute; inset: 0 0 auto 0; height: 3px;
      background: linear-gradient(90deg, var(--kv-accent), var(--kv-neon));
      opacity: 0.8;
    }
    .kv-stat-ico {
      width: 34px; height: 34px; border-radius: 9px; margin-bottom: 10px;
      background: var(--kv-surface-2); color: var(--kv-accent);
      display: inline-flex; align-items: center; justify-content: center;
    }
    .kv-stat-label { color: var(--kv-text-muted); font-size: 0.8125rem; }
    .kv-qa-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 14px; }
    .kv-qa {
      display: flex; align-items: flex-start; gap: 12px; text-align: left;
      background: var(--kv-surface); border: 1px solid var(--kv-border);
      border-radius: 12px; padding: 14px; cursor: pointer;
      transition: transform 0.15s ease, border-color 0.15s ease;
    }
    .kv-qa:hover { transform: translateY(-2px); border-color: var(--kv-accent); }
    .kv-qa-ico {
      width: 38px; height: 38px; flex-shrink: 0; border-radius: 10px;
      display: inline-flex; align-items: center; justify-content: center;
      background: linear-gradient(135deg, var(--kv-accent), var(--kv-neon)); color: #FFFFFF;
    }
    .kv-qa-title { display: block; font-weight: 700; font-size: 0.875rem; }
    .kv-qa-desc { display: block; color: var(--kv-text-muted); font-size: 0.75rem; margin-top: 2px; }
    .kv-admin-shell .kv-stat-box { border-radius: 14px; }
    .kv-admin-shell table.kv-table th {
      text-transform: uppercase; letter-spacing: 0.06em; background: var(--kv-surface-2);
    }
    .kv-admin-shell table.kv-table tbody tr { transition: background-color 0.12s ease; }
    .kv-admin-shell table.kv-table tbody tr:hover { background: var(--kv-surface-2); }
    .kv-btn-sm { padding: 6px 10px; font-size: 0.75rem; border-radius: 7px; }
    .kv-btn-danger-ghost {
      background: transparent; color: var(--kv-danger); border-color: var(--kv-border);
    }
    .kv-btn-danger-ghost:hover { border-color: var(--kv-danger); }

    .kv-form-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }
    .kv-page-thumb {
      width: 44px; height: 58px; object-fit: cover; border-radius: 6px;
      border: 1px solid var(--kv-border); background: var(--kv-surface-2);
    }
    .kv-badge {
      display: inline-flex; align-items: center; padding: 2px 10px;
      border-radius: 999px; font-size: 0.75rem; font-weight: 600;
      border: 1px solid var(--kv-border); color: var(--kv-text-muted);
    }
    .kv-badge-ok { color: var(--kv-success); border-color: var(--kv-success); }
    .kv-badge-pending { color: var(--kv-warning); border-color: var(--kv-warning); }
    .kv-badge-reject { color: var(--kv-danger); border-color: var(--kv-danger); }
    .kv-toasts {
      position: fixed; bottom: 20px; right: 20px; z-index: 100;
      display: flex; flex-direction: column; gap: 10px; max-width: 340px;
    }
    .kv-toast {
      padding: 12px 16px; border-radius: 10px; font-size: 0.875rem;
      background: var(--kv-surface-2); border: 1px solid var(--kv-border);
      color: var(--kv-text); box-shadow: 0 8px 24px rgba(0, 0, 0, 0.35);
      animation: kv-toast-in 0.18s ease;
    }
    .kv-toast-ok { border-color: var(--kv-success); }
    .kv-toast-warn { border-color: var(--kv-warning); }
    .kv-toast-err { border-color: var(--kv-danger); }
    @keyframes kv-toast-in {
      from { opacity: 0; transform: translateY(8px); }
      to { opacity: 1; transform: none; }
    }
    .kv-modal {
      position: fixed; inset: 0; background: rgba(0, 0, 0, 0.55); z-index: 90;
      display: flex; align-items: center; justify-content: center; padding: 20px;
    }
    .kv-modal-box {
      background: var(--kv-surface); border: 1px solid var(--kv-border);
      border-radius: 12px; padding: 24px; max-width: 440px; width: 100%;
    }

    /* Polish SaaS publik: kicker, chip, glow, gradien */
    .kv-kicker {
      font-size: 0.75rem; font-weight: 700; letter-spacing: 0.1em;
      text-transform: uppercase; color: var(--kv-neon); margin: 0 0 4px;
    }
    .kv-chip {
      display: inline-flex; align-items: center; padding: 2px 9px;
      border-radius: 999px; background: var(--kv-surface-2);
      border: 1px solid var(--kv-border); font-size: 0.6875rem;
      font-weight: 600; color: var(--kv-text-muted); white-space: nowrap;
    }
    .kv-chip-accent {
      color: var(--kv-neon); border-color: var(--kv-accent);
      border-color: color-mix(in srgb, var(--kv-neon) 45%, transparent);
    }
    .kv-hero { position: relative; overflow: hidden; }
    .kv-hero::before {
      content: ''; position: absolute; top: -120px; right: -80px;
      width: 380px; height: 380px; border-radius: 50%;
      background: radial-gradient(closest-side, rgba(99, 102, 241, 0.22), transparent);
      pointer-events: none;
    }
    .kv-hero::after {
      content: ''; position: absolute; bottom: -140px; left: -60px;
      width: 320px; height: 320px; border-radius: 50%;
      background: radial-gradient(closest-side, rgba(34, 211, 238, 0.14), transparent);
      pointer-events: none;
    }
    .kv-hero .kv-cover-wrap { box-shadow: 0 0 0 1px var(--kv-border), 0 24px 60px -24px rgba(0, 0, 0, 0.55); }
    .kv-card { border-radius: 14px; }
    .kv-card:hover { box-shadow: 0 14px 34px -14px rgba(99, 102, 241, 0.4); }
    .kv-card .kv-cover-wrap img { transition: transform 0.25s ease; }
    .kv-card:hover .kv-cover-wrap img { transform: scale(1.05); }
    .kv-card-title {
      display: -webkit-box; -webkit-line-clamp: 2;
      -webkit-box-orient: vertical; overflow: hidden;
    }
    .kv-btn-primary { background: linear-gradient(135deg, var(--kv-accent), var(--kv-neon)); }
    .kv-btn-primary:hover {
      background: linear-gradient(135deg, var(--kv-accent-hover), var(--kv-neon));
      box-shadow: 0 6px 18px -6px rgba(99, 102, 241, 0.5);
    }
    .kv-input, .kv-textarea { border-radius: 10px; }
    .kv-select { border-radius: 999px; }
    .kv-input:focus, .kv-select:focus, .kv-textarea:focus {
      outline: none; border-color: var(--kv-accent);
      box-shadow: 0 0 0 3px rgba(99, 102, 241, 0.18);
    }
    .kv-chapter-row {
      border: 1px solid var(--kv-border); border-radius: 10px;
      margin-bottom: 8px; padding: 12px 16px;
      transition: border-color 0.15s ease, background-color 0.15s ease;
    }
    .kv-chapter-row:last-child { margin-bottom: 0; }
    .kv-chapter-row:hover { border-color: var(--kv-accent); background: var(--kv-surface-2); }
    .kv-reader-progress { background: linear-gradient(90deg, var(--kv-accent), var(--kv-neon)); }
    .kv-reader-bar {
      background: var(--kv-surface);
      background: color-mix(in srgb, var(--kv-surface) 86%, transparent);
      backdrop-filter: blur(12px);
    }
    table.kv-table th { text-transform: uppercase; letter-spacing: 0.05em; }
    table.kv-table tbody tr { transition: background-color 0.12s ease; }
    table.kv-table tbody tr:hover { background: var(--kv-surface-2); }
    .kv-stat-box { border-radius: 14px; }
    .kv-footer { background: var(--kv-surface); }
    .kv-404 { text-shadow: 0 0 40px rgba(99, 102, 241, 0.55); }
    ::-webkit-scrollbar { width: 10px; height: 10px; }
    ::-webkit-scrollbar-thumb { background: var(--kv-border); border-radius: 999px; }
    ::-webkit-scrollbar-thumb:hover { background: var(--kv-text-muted); }
    ::-webkit-scrollbar-track { background: transparent; }

    /* Soft modern SaaS visual system */
    html { scroll-behavior: smooth; }
    body {
      min-height: 100vh;
      background:
        radial-gradient(ellipse at 50% -18%, color-mix(in srgb, var(--kv-accent) 7%, transparent), transparent 46%),
        var(--kv-bg);
      letter-spacing: -0.012em;
    }
    h1, h2, h3, p { text-wrap: pretty; }
    .kv-container { max-width: 1280px; padding-right: 32px; padding-left: 32px; }
    .kv-header {
      background: color-mix(in srgb, var(--kv-bg) 88%, transparent);
      border-bottom-color: color-mix(in srgb, var(--kv-border) 84%, transparent);
      box-shadow: 0 8px 26px -24px rgba(30, 35, 60, 0.42);
    }
    html.dark .kv-header { box-shadow: 0 8px 26px -24px rgba(0, 0, 0, 0.8); }
    .kv-header-inner { height: 72px; }
    .kv-brand {
      font-size: 1.22rem;
      letter-spacing: -0.06em;
      color: var(--kv-text);
    }
    .kv-brand-mark {
      width: 36px;
      height: 36px;
      flex-basis: 36px;
      border: 0;
      border-radius: 12px;
      background: linear-gradient(145deg, var(--kv-accent), var(--kv-neon));
      box-shadow: 0 7px 16px -10px var(--kv-accent);
    }
    .kv-nav { gap: 5px; }
    .kv-nav-link {
      padding: 8px 12px;
      border: 0;
      border-radius: 10px;
      font-size: 0.84rem;
      transition: background-color 0.18s ease, color 0.18s ease;
    }
    .kv-nav-link:hover, .kv-nav-link.active {
      color: var(--kv-accent);
      background: color-mix(in srgb, var(--kv-accent) 9%, var(--kv-surface));
    }
    .kv-nav-login, .kv-nav-login:hover, .kv-nav-login.active {
      color: #FFFFFF !important;
      background: var(--kv-accent);
      box-shadow: 0 7px 18px -12px var(--kv-accent);
    }
    .kv-nav-login:hover { background: var(--kv-accent-hover); }
    .kv-theme-toggle {
      width: 42px;
      height: 42px;
      flex-basis: 42px;
      border-radius: 12px;
      background: var(--kv-surface);
      border-color: var(--kv-border);
    }
    .kv-btn {
      min-height: 42px;
      border-radius: 11px;
      font-weight: 650;
      letter-spacing: -0.01em;
