      html.dark body.kv-home-route {
        --kv-bg: #0f111a;
        --kv-surface: #171a27;
        --kv-surface-2: #20243a;
        --kv-border: #2b304c;
        --kv-text: #dee1fe;
        --kv-text-muted: #a0a7b8;
        --kv-accent: #6558d9;
        --kv-accent-hover: #6558d9;
        --kv-success: #22c55e;
        --kv-warning: #f59e0b;
        --kv-danger: #ef4444;
        --kv-radius: 16px;
        background: #0f111a;
        -webkit-font-smoothing: antialiased;
