        position: relative; overflow: hidden; border-radius: 24px; padding: 28px; margin: 16px 0 20px;
        background: linear-gradient(135deg, #171a27 0%, #20243a 55%, #171a27 100%);
        border: 1px solid #2b304c; box-shadow: 0 20px 40px -18px rgba(101,88,217,.35);
