      html.dark body.kv-home-route .kv-home-hero::after { content: ""; position: absolute; left: -80px; bottom: -80px; width: 280px; height: 280px; border-radius: 999px; background: rgba(168,85,247,.14); filter: blur(50px); pointer-events: none; }
